export default function DiplomatForma() {
  useEffect(() => {
    const a=document.getElementById('bg'); const sb=document.getElementById('sound');
    let on=false;
    const icons={off:'<path d="M4 9v6h4l5 4V5L8 9H4z"/><path d="M17 9l4 6M21 9l-4 6"/>',on:'<path d="M4 9v6h4l5 4V5L8 9H4z"/><path d="M16 8a5 5 0 0 1 0 8"/><path d="M19 5a9 9 0 0 1 0 14"/>'};
    const setIcon=()=>{const svg=sb&&sb.querySelector('svg'); if(svg) svg.innerHTML=on?icons.on:icons.off;};
    const onSound=()=>{on=!on; if(on){a.volume=0;a.play().then(()=>{let v=0;const f=setInterval(()=>{v=Math.min(0.6,v+0.04);a.volume=v;if(v>=0.6)clearInterval(f)},60)}).catch(()=>{});}else{a.pause();} setIcon();};
    if(sb) sb.addEventListener('click',onSound); setIcon();
    const nav=document.getElementById('nav'); const burger=document.getElementById('burger');
    const onBurger=()=>nav&&nav.classList.toggle('open');
    if(burger) burger.addEventListener('click',onBurger);
    const closers=Array.from(document.querySelectorAll('[data-close]'));
    const onClose=()=>nav&&nav.classList.remove('open');
    closers.forEach(l=>l.addEventListener('click',onClose));
    const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}}),{threshold:.12});
    Array.from(document.querySelectorAll('.rv')).forEach(el=>io.observe(el));
    return ()=>{ io.disconnect(); if(sb)sb.removeEventListener('click',onSound); if(burger)burger.removeEventListener('click',onBurger); closers.forEach(l=>l.removeEventListener('click',onClose)); if(a){a.pause();} };
  }, []);
  return (
    <>
      <style dangerouslySetInnerHTML={{ __html: STYLE }} />
      <div dangerouslySetInnerHTML={{ __html: MARKUP }} />
    </>
  );
}
